                            quiz: [
                                { q: "ما هو المستخدم الذي يملك الصلاحيات الكاملة في نظام Linux؟", options: ["Admin", "Root", "Guest"], correct: 1 },
                                { q: "لماذا يفضل الهكرز استخدام Linux (مثل Kali)؟", options: ["لأنه يشغل الألعاب بشكل أفضل", "لأنه يحتوي على أدوات مسبقة ومرونة عالية في التحكم بالشبكة", "لأنه أجمل في التصميم"], correct: 1 }
                            ]
