                                { q: "ما هي ميزة حمولة Meterpreter الأساسية؟", options: ["تعمل داخل الذاكرة ولا تترك أثراً على القرص", "تسرع الإنترنت", "تقوم بمسح الفيروسات"], correct: 0 }
