  // ============================================================
    //  💪 المحركات الاحترافية (Pro Engines) - ألصق هذا الجزء في الأسفل
    // ============================================================

    // 1. محرك التيرمينال الشامل (Universal Terminal Engine)
    // هذا المحرك سنستخدمه لكل دروس سطر الأوامر (Nmap, Linux, Bash)
    function renderTerminalLab(container, stepsList, completeBtn, feedback, config) {
        stepsList.innerHTML = config.stepsText;
        
        container.innerHTML = `
            <div class="w-full max-w-2xl h-[400px] bg-[#0c0c0c] rounded-lg border border-gray-700 shadow-2xl flex flex-col font-mono text-sm relative overflow-hidden">
                <div class="bg-gray-800 px-4 py-2 flex items-center gap-2 border-b border-gray-700">
                    <div class="flex gap-1.5">
                        <div class="w-3 h-3 rounded-full bg-red-500"></div>
                        <div class="w-3 h-3 rounded-full bg-yellow-500"></div>
                        <div class="w-3 h-3 rounded-full bg-green-500"></div>
                    </div>
                    <div class="text-gray-400 text-xs ml-2">Terminal - Root Access</div>
                </div>
                
                <div class="flex-grow p-4 overflow-y-auto custom-scrollbar" id="term-body" style="font-family: 'Courier New', monospace;">
                    <div class="text-green-500 mb-2">Welcome to Pharaoh OS v2.0</div>
                    <div class="text-gray-500 mb-4">Type 'help' for available commands.</div>
                    
                    <div id="term-history"></div>
                    
                    <div class="flex items-center text-white">
                        <span class="text-green-400 mr-2 shrink-0">${config.prompt}</span>
                        <input type="text" id="term-input" class="bg-transparent border-none outline-none flex-grow text-white" autocomplete="off" autofocus>
                    </div>
                </div>
            </div>
        `;

        const input = container.querySelector('#term-input');
        const history = container.querySelector('#term-history');
        const body = container.querySelector('#term-body');

        // التركيز دائماً على المؤشر
        container.addEventListener('click', () => input.focus());

        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                const cmd = input.value.trim();
                
                // إضافة الأمر للسجل
                const cmdLine = document.createElement('div');
                cmdLine.innerHTML = `<span class="text-green-400 mr-2">${config.prompt}</span><span class="text-white">${cmd}</span>`;
                history.appendChild(cmdLine);
                input.value = '';

                // معالجة الأمر (Simulated Delay)
                const loadingLine = document.createElement('div');
                loadingLine.className = 'text-gray-400 animate-pulse';
                loadingLine.textContent = 'Executing...';
                history.appendChild(loadingLine);

                setTimeout(() => {
                    loadingLine.remove();
                    const responseDiv = document.createElement('div');
                    responseDiv.className = 'text-gray-300 mb-2 whitespace-pre-wrap leading-tight';

                    if (config.validCommands[cmd]) {
                        // أمر صحيح
                        const result = config.validCommands[cmd];
                        responseDiv.innerHTML = result.output;
                        history.appendChild(responseDiv);
                        
                        if (result.isSuccess) {
                            labSuccess(completeBtn, feedback, result.successMsg);
                            input.disabled = true;
                        }
                    } else if (cmd === 'clear') {
                        history.innerHTML = '';
                    } else if (cmd === '') {
                        // Do nothing
                    } else {
                        // أمر خاطئ
                        responseDiv.className = 'text-red-400 mb-2';
                        responseDiv.textContent = `bash: ${cmd}: command not found`;
                        history.appendChild(responseDiv);
                        labError(feedback, "أمر غير صحيح. راجع التعليمات وحاول مرة أخرى.");
                    }
                    
                    // التمرير للأسفل
                    body.scrollTop = body.scrollHeight;
                }, 600); // تأخير بسيط للواقعية
            }
        });
    }

    // 2. محرك OSI Model (Drag & Drop الاحترافي)
    function renderOSILabPro(container, stepsList, completeBtn, feedback) {
        stepsList.innerHTML = '<li>رتب طبقات نموذج OSI السبعة بالترتيب الصحيح من الأسفل (1) إلى الأعلى (7).</li><li>اسحب اسم الطبقة وضعه في مكانه الصحيح.</li>';
        
        container.innerHTML = `
            <div class="flex w-full gap-4 h-[450px]">
                <div class="w-1/3 flex flex-col gap-2 p-2 bg-white/5 rounded border border-white/10" id="source-zone">
                    </div>

                <div class="w-2/3 flex flex-col gap-2 relative">
                    <div class="absolute -right-8 top-0 h-full flex flex-col justify-between py-4 text-xs text-gray-500 font-mono">
                        <span>L7</span><span>L6</span><span>L5</span><span>L4</span><span>L3</span><span>L2</span><span>L1</span>
                    </div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="7">Application</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="6">Presentation</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="5">Session</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="4">Transport</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="3">Network</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="2">Data Link</div>
                    <div class="drop-zone h-12 bg-black/40 border border-dashed border-gray-600 rounded flex items-center justify-center text-gray-600" data-id="1">Physical</div>
                </div>
            </div>
        `;

        const layers = [
            {id: 1, name: "Physical (الفيزيائية)"},
            {id: 2, name: "Data Link (الربط)"},
            {id: 3, name: "Network (الشبكة)"},
            {id: 4, name: "Transport (النقل)"},
            {id: 5, name: "Session (الجلسة)"},
            {id: 6, name: "Presentation (التقديم)"},
            {id: 7, name: "Application (التطبيق)"}
        ].sort(() => Math.random() - 0.5); // خلط عشوائي

        const sourceZone = container.querySelector('#source-zone');
        
        layers.forEach(l => {
            const el = document.createElement('div');
            el.className = 'draggable-item bg-cyber-blue/10 border border-cyber-blue text-cyber-blue p-2 rounded cursor-grab active:cursor-grabbing text-center text-sm font-bold shadow-lg';
            el.draggable = true;
            el.textContent = l.name;
            el.dataset.id = l.id;
            
            el.addEventListener('dragstart', e => {
                e.dataTransfer.setData('text/plain', l.id);
                e.target.classList.add('opacity-50');
            });
            el.addEventListener('dragend', e => e.target.classList.remove('opacity-50'));
            
            sourceZone.appendChild(el);
        });

        const dropZones = container.querySelectorAll('.drop-zone');
        let correctCount = 0;

        dropZones.forEach(zone => {
            zone.addEventListener('dragover', e => {
                e.preventDefault();
                zone.classList.add('bg-white/10');
            });
            zone.addEventListener('dragleave', e => zone.classList.remove('bg-white/10'));
            
            zone.addEventListener('drop', e => {
                e.preventDefault();
                zone.classList.remove('bg-white/10');
                const id = e.dataTransfer.getData('text/plain');
                const targetId = zone.dataset.id;

                if (id === targetId) {
                    // إجابة صحيحة
                    zone.innerHTML = '';
                    zone.classList.remove('border-dashed', 'text-gray-600', 'bg-black/40');
                    zone.classList.add('bg-green-600', 'text-white', 'border-solid', 'border-green-400');
                    
                    // البحث عن العنصر الأصلي وإخفائه
                    const original = document.querySelector(`.draggable-item[data-id="${id}"]`);
                    if(original) {
                        zone.textContent = original.textContent;
                        original.remove();
                    }
                    
                    correctCount++;
                    if(correctCount === 7) {
                        labSuccess(completeBtn, feedback, "عبقري! لقد بنيت الهيكل الأساسي للإنترنت بشكل صحيح.");
                    }
                } else {
                    labError(feedback, "مكان خاطئ! حاول مرة أخرى.");
                }
            });
        });
    }

    // 3. محرك TCP Handshake (Interactive Animation)
    function renderTCPHandshakeLabPro(container, stepsList, completeBtn, feedback) {
        stepsList.innerHTML = '<li>بروتوكول TCP يتطلب "مصافحة" قبل إرسال البيانات.</li><li>اضغط الأزرار بالترتيب لإتمام الاتصال: SYN ثم SYN-ACK ثم ACK.</li>';
        
        container.innerHTML = `
            <div class="w-full h-full flex flex-col justify-between py-10 relative">
                <div class="flex justify-between px-10">
                    <div class="text-center z-10">
                        <div class="w-16 h-16 bg-blue-600 rounded-lg flex items-center justify-center text-3xl shadow-[0_0_20px_blue]">💻</div>
                        <div class="mt-2 font-bold text-blue-400">Client</div>
                    </div>
                    <div class="text-center z-10">
                        <div class="w-16 h-16 bg-purple-600 rounded-lg flex items-center justify-center text-3xl shadow-[0_0_20px_purple]">🖥️</div>
                        <div class="mt-2 font-bold text-purple-400">Server</div>
                    </div>
                </div>

                <div class="absolute top-16 left-20 right-20 h-1 bg-gray-700 top-[60px]"></div>

                <div class="flex-grow relative" id="packet-zone"></div>

                <div class="flex justify-center gap-4 mt-8">
                    <button id="btn-syn" class="btn-cyber px-6 py-2">1. Send SYN</button>
                    <button id="btn-syn-ack" class="btn-cyber px-6 py-2 opacity-50 cursor-not-allowed" disabled>2. Send SYN-ACK</button>
                    <button id="btn-ack" class="btn-cyber px-6 py-2 opacity-50 cursor-not-allowed" disabled>3. Send ACK</button>
                </div>
            </div>
        `;

        const btnSyn = container.querySelector('#btn-syn');
        const btnSynAck = container.querySelector('#btn-syn-ack');
        const btnAck = container.querySelector('#btn-ack');
        const zone = container.querySelector('#packet-zone');

        function sendPacket(type, direction) { // direction: 'right' or 'left'
            const packet = document.createElement('div');
            packet.className = `absolute top-1/2 -translate-y-1/2 px-3 py-1 rounded text-xs font-bold text-white shadow-lg transition-all duration-1000 ease-in-out`;
            packet.style.backgroundColor = direction === 'right' ? '#3B82F6' : '#9333EA'; // Blue or Purple
            packet.textContent = type;
            
            if (direction === 'right') {
                packet.style.left = '10%';
                zone.appendChild(packet);
                setTimeout(() => packet.style.left = '85%', 50);
            } else {
                packet.style.left = '85%';
                zone.appendChild(packet);
                setTimeout(() => packet.style.left = '10%', 50);
            }

            setTimeout(() => {
                packet.classList.add('opacity-0'); // Fade out
                setTimeout(() => packet.remove(), 500);
            }, 1000);
        }

        btnSyn.onclick = () => {
            sendPacket('SYN', 'right');
            btnSyn.disabled = true; btnSyn.classList.add('opacity-50');
            setTimeout(() => {
                btnSynAck.disabled = false; btnSynAck.classList.remove('opacity-50', 'cursor-not-allowed');
                btnSynAck.classList.add('animate-pulse');
            }, 1200);
        };

        btnSynAck.onclick = () => {
            sendPacket('SYN-ACK', 'left');
            btnSynAck.disabled = true; btnSynAck.classList.add('opacity-50');
            btnSynAck.classList.remove('animate-pulse');
            setTimeout(() => {
                btnAck.disabled = false; btnAck.classList.remove('opacity-50', 'cursor-not-allowed');
                btnAck.classList.add('animate-pulse');
            }, 1200);
        };

        btnAck.onclick = () => {
            sendPacket('ACK', 'right');
            btnAck.disabled = true; btnAck.classList.add('opacity-50');
            btnAck.classList.remove('animate-pulse');
            setTimeout(() => {
                container.querySelector('.bg-gray-700').classList.replace('bg-gray-700', 'bg-green-500'); // Turn wire green
                container.querySelector('.bg-gray-700')?.classList.add('shadow-[0_0_10px_green]');
                labSuccess(completeBtn, feedback, "تم إنشاء الاتصال بنجاح! القناة الآن مفتوحة وموثوقة.");
            }, 1200);
        };
    }

