        /* ------ LAB IMPLEMENTATIONS (Kept as is for compatibility) ------ */
        function renderShieldLab(container, steps, btn, feedback) {
            steps.innerHTML = '<li>الشبكة تتعرض لهجوم (حزم حمراء تتدفق بسرعة).</li><li>اضغط على زر "تفعيل حقل الحماية" لردع الهجوم.</li><li>شاهد كيف يتم صد الهجوم ومنع وصوله للمفاعل.</li>';
            const shield = document.createElement('div');
            shield.className = 'w-32 h-32 border-4 border-gray-600 rounded-full flex items-center justify-center transition-all duration-500 relative z-10 bg-black/50';
            shield.innerHTML = '<svg class="w-16 h-16 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"></path></svg>';
            const activateBtn = document.createElement('button');
            activateBtn.textContent = "تفعيل حقل الحماية";
            activateBtn.className = 'btn-cyber px-6 py-2 mt-8 absolute bottom-10 z-20';
            container.appendChild(shield);
            container.appendChild(activateBtn);
            let isActive = false;
            const interval = setInterval(() => {
                const packet = document.createElement('div');
                packet.className = 'lab-packet';
                packet.style.right = '0px';
                packet.style.top = Math.random() * 80 + 10 + '%';
                container.appendChild(packet);
                let pos = 0;
                const move = setInterval(() => {
                    pos += 5;
                    packet.style.right = pos + 'px';
                    if (pos > container.clientWidth / 2 - 40 && isActive) {
                        packet.style.backgroundColor = '#00F0FF';
                        packet.style.boxShadow = '0 0 10px #00F0FF';
                        packet.style.transform = 'scale(0)';
                        setTimeout(() => packet.remove(), 200);
                        clearInterval(move);
                    } else if (pos > container.clientWidth) {
                        packet.remove();
                        clearInterval(move);
                    }
                }, 15); 
            }, 350); 
            activateBtn.onclick = () => {
                isActive = true;
                shield.classList.add('shield-active');
                shield.style.borderColor = '#00F0FF';
                shield.querySelector('svg').classList.remove('text-gray-600');
                shield.querySelector('svg').classList.add('text-cyber-blue');
                activateBtn.textContent = "المفاعل محمي ✅";
                activateBtn.disabled = true;
                labSuccess(btn, feedback, "تم تأمين الشبكة بنجاح! حقل الحماية (الجدار الناري) يعمل بكفاءة.");
            };
            btn.addEventListener('click', () => clearInterval(interval));
        }

