        function renderPasswordLab(container, steps, btn, feedback) {
            steps.innerHTML = '<li>أنشئ كلمة مرور "قوية" (يجب أن تحتوي على أكثر من 8 أحرف ورقم واحد على الأقل).</li><li>قم بتفعيل خيار المصادقة الثنائية (2FA) لحفظ الإعدادات.</li>';
            const form = document.createElement('div');
            form.className = 'glass-panel p-6 w-64 flex flex-col gap-4';
            form.innerHTML = `
                <input type="text" id="pass-input" placeholder="كلمة المرور..." class="bg-black/50 border border-gray-600 p-2 rounded text-white focus:border-cyber-gold outline-none">
                <div class="flex items-center justify-between text-sm text-gray-400">
                    <span>المصادقة الثنائية (2FA)</span>
                    <input type="checkbox" id="2fa-toggle" class="w-4 h-4 accent-cyber-blue">
                </div>
                <div id="strength-meter" class="h-1 w-full bg-gray-700 rounded overflow-hidden"><div id="meter-fill" class="h-full w-0 bg-red-500 transition-all"></div></div>
                <div id="status-msg" class="text-xs text-center min-h-[1.5rem] text-gray-500">ادخل كلمة مرور للتحقق...</div>
                <button id="save-pass" class="btn-cyber py-1 text-sm" disabled>حفظ الإعدادات</button>
            `;
            container.appendChild(form);
            const input = form.querySelector('#pass-input');
            const meter = form.querySelector('#meter-fill');
            const toggle = form.querySelector('#2fa-toggle');
            const save = form.querySelector('#save-pass');
            const statusMsg = form.querySelector('#status-msg');
            
            let isStrong = false;
            let is2FA = false;

            const checkStrength = () => {
                const val = input.value;
                const hasNumber = /\d/.test(val);
                const isLong = val.length >= 8;
                
                if (isLong && hasNumber) { 
                    meter.style.width = '100%'; 
                    meter.className = 'h-full w-full bg-green-500 transition-all';
                    statusMsg.textContent = "كلمة مرور قوية! الآن قم بتفعيل 2FA.";
                    isStrong = true;
                }
                else if (val.length > 4) { 
                    meter.style.width = '50%'; 
                    meter.className = 'h-full w-full bg-yellow-500 transition-all';
                    statusMsg.textContent = "كلمة مرور متوسطة. أضف أرقاماً ورموزاً.";
                    isStrong = false;
                }
                else { 
                    meter.style.width = '10%'; 
                    meter.className = 'h-full w-full bg-red-500 transition-all';
                    statusMsg.textContent = "كلمة مرور ضعيفة.";
                    isStrong = false;
                }
                
                // Check 2FA state from UI
                is2FA = toggle.checked;

                // Update save button state
                if (isStrong && is2FA) {
                    save.disabled = false;
                    save.classList.remove('opacity-50');
                } else {
                    save.disabled = true;
                    save.classList.add('opacity-50');
                }
            };
            
            input.addEventListener('input', checkStrength);
            
            toggle.addEventListener('change', () => {
                is2FA = toggle.checked;
                if(is2FA && isStrong) {
                    statusMsg.textContent = "2FA مفعل. يمكنك الآن حفظ الإعدادات!";
                } else if (is2FA && !isStrong) {
                    statusMsg.textContent = "2FA مفعل، لكن كلمة المرور ضعيفة. يرجى تقويتها أولاً.";
                }
                checkStrength();
            });

            save.onclick = () => {
                if (isStrong && is2FA) {
                    labSuccess(btn, feedback, "كلمة مرور قوية + حماية مضاعفة. حسابك آمن بالكامل!");
                } else {
                    labError(feedback, "الرجاء التأكد من قوة كلمة المرور وتفعيل المصادقة الثنائية.");
                }
            };
        }
        
